from typing import Sequence


def key_match_paged(key0: list[int], key1: list[int], page_size: int) -> int:
    """Return the common prefix length, rounded down to whole pages.

    The result counts only leading tokens that are identical in both keys.
    Any partially matching final page is excluded, just like RadixKey.match
    with ``page_size > 1``.
    """
    if page_size < 1:
        raise ValueError("page_size must be at least 1")

    matched = 0
    for token0, token1 in zip(key0, key1):
        if token0 != token1:
            break
        matched += 1

    return (matched // page_size) * page_size


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------


import pytest


def test_exact_multiple_pages():
    assert key_match_paged([1, 2, 3, 4, 5, 6], [1, 2, 3, 4, 5, 6], 2) == 6


def test_partial_trailing_page_is_not_counted():
    assert key_match_paged([1, 2, 3, 4, 5], [1, 2, 3, 4, 9], 2) == 4
    assert key_match_paged([1, 2, 3], [1, 2, 3], 2) == 2


def test_mismatch_before_first_page():
    assert key_match_paged([1, 9, 3, 4], [1, 2, 3, 4], 2) == 0
    assert key_match_paged([9], [1], 1) == 0


def test_page_size_one_returns_raw_common_prefix():
    assert key_match_paged([1, 2, 3, 9], [1, 2, 3, 4], 1) == 3


def test_difference_after_complete_pages():
    assert key_match_paged([1, 2, 3, 4, 5, 6], [1, 2, 3, 4, 7, 8], 2) == 4


def test_empty_keys_and_oversized_page():
    assert key_match_paged([], [1, 2, 3], 2) == 0
    assert key_match_paged([1, 2, 3], [], 2) == 0
    assert key_match_paged([1, 2, 3], [1, 2, 3], 4) == 0


def test_invalid_page_size():
    with pytest.raises(ValueError):
        key_match_paged([1], [1], 0)
